{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C53"],
      "claim": "Cilomilast showed a mean absolute bioavailability of 96% (range 92–102%) in healthy volunteers in the fasted state after a 10 mg oral solution versus IV infusion, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Esaxerenone showed an absolute bioavailability of 89.0% in the fasting state after a single oral 5-mg dose in healthy Japanese subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Danazol showed an absolute bioavailability of 19% in the fasted state after a 100 mg capsule versus IV, which is below the 20% threshold and argues for low bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred evidence molecules show absolute oral bioavailability at or above 20%, including direct fasted absolute measurements of 30–96%. One high-transfer molecule showed fasted absolute bioavailability below 20% (11–19%), but the weight of direct numeric evidence supports high bioavailability.",
  "evidence_gaps": [
    "Molecule 1 has fasted absolute bioavailability below 20% (11–19%) while fed-state values are ≥44%; fed-state records were discounted as altered conditions.",
    "Molecule 9 has one qualitative report of very low bioavailability despite numeric records of 34.9–56.2%; this conflict remains unresolved.",
    "Molecule 10 includes a record referring to abacavir rather than amprenavir; this provenance conflict was discounted."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

